#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Usage: scripts/store-listing-wizard.sh he|ar
# Puts a localized listing (legal/STORE_LISTINGS_HE_AR.txt) and its screenshots into App Store
# Connect and Play Console, one field at a time, copying each value to the clipboard.

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
LISTINGS="$ROOT/legal/STORE_LISTINGS_HE_AR.txt"

# listing LANG STORE LABEL prints one field. STORE is "App Store", "Google Play" or "Full description".
listing() {
  node -e '
    const [file, lang, store, label] = process.argv.slice(1);
    const text = require("fs").readFileSync(file, "utf8").replace(/\r/g, "");
    const block = text.split(/^=+ [A-Z]+ \((\w+)\) =+$/m);
    const body = block[block.indexOf(lang) + 1];
    if (!body) process.exit(1);
    const section = body.split(/^--- (.+?) ---$/m);
    const content = section[section.findIndex((s) => s.startsWith(store)) + 1] || "";
    if (store.startsWith("Full description")) { process.stdout.write(content.trim()); process.exit(0); }
    const m = content.match(new RegExp("^" + label + " \\(\\u2264\\d+\\): (.+)$", "m"));
    if (!m) process.exit(1);
    process.stdout.write(m[1].trim());
  ' "$LISTINGS" "$@"
}

# copy_field "Label" VALUE puts VALUE on the clipboard (UTF-8 safe on Windows), shows it, and waits.
copy_field() {
  local label="$1" value="$2" tmp
  tmp=$(mktemp)
  printf '%s' "$value" > "$tmp"
  if command -v powershell.exe >/dev/null 2>&1; then
    local win; win=$(cygpath -w "$tmp" 2>/dev/null || wslpath -w "$tmp" 2>/dev/null || echo "$tmp")
    powershell.exe -NoProfile -Command "Get-Content -Raw -Encoding UTF8 '$win' | Set-Clipboard" >/dev/null 2>&1 || true
  elif command -v pbcopy >/dev/null 2>&1; then pbcopy < "$tmp"
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy < "$tmp"
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard < "$tmp"
  fi
  rm -f "$tmp"
  printf '\n  %s%s%s %s(copied to clipboard)%s\n' "$BOLD" "$label" "$RESET" "$DIM" "$RESET"
  printf '%s\n' "$value" | head -n 4 | sed 's/^/    /'
  (( $(printf '%s\n' "$value" | wc -l) > 4 )) && note "    …"
  pause "Pasted? Press Enter for the next field"
}

open_folder() {
  local dir="$1"
  if command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$(cygpath -w "$dir" 2>/dev/null || wslpath -w "$dir")" || true
  elif command -v open >/dev/null 2>&1; then open "$dir"
  elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$dir"
  fi >/dev/null 2>&1
  say "Folder: $dir"
}

run_wizard() {

LANG_CODE="${1:-}"
case "$LANG_CODE" in
  he) LANG_NAME="Hebrew"; PLAY_LANG="Hebrew – iw-IL" ;;
  ar) LANG_NAME="Arabic"; PLAY_LANG="Arabic – ar" ;;
  *) echo "Usage: $0 he|ar" >&2; exit 1 ;;
esac
SHOTS="$ROOT/assets/store/appstore/$LANG_CODE"
[[ -d "$SHOTS/iphone-1206x2622" ]] || { echo "No screenshots in $SHOTS; run assets/store/appstore/src/render.sh $LANG_CODE" >&2; exit 1; }
listing "$LANG_CODE" "App Store" "Name" >/dev/null || { echo "No $LANG_CODE listing in $LISTINGS" >&2; exit 1; }

TOTAL_STAGES=5

banner "Pinch store listing: $LANG_NAME"

stage "App Store Connect: add $LANG_NAME"
say "Name, subtitle and keywords only change with a new version, so do this on the version"
say "you're about to submit (or create one: '+' next to iOS App)."
open_url "https://appstoreconnect.apple.com/apps/6796310453/distribution"
step "Open the version in 'Prepare for Submission'."
step "Top right, open the language menu (it shows English (U.S.)) → $LANG_NAME."
pause "Done? Press Enter"

stage "App Store Connect: $LANG_NAME text"
step "Still on the $LANG_NAME version page, paste each field as it's copied."
copy_field "Promotional Text" "$(listing "$LANG_CODE" "App Store" "Promotional text")"
copy_field "Description" "$(listing "$LANG_CODE" "Full description")"
copy_field "Keywords" "$(listing "$LANG_CODE" "App Store" "Keywords")"
step "Scroll to App Information (left menu, General → App Information) for name and subtitle,"
step "with $LANG_NAME picked in the same language menu."
copy_field "Name" "$(listing "$LANG_CODE" "App Store" "Name")"
copy_field "Subtitle" "$(listing "$LANG_CODE" "App Store" "Subtitle")"
step "Click Save on both pages."
pause "Saved? Press Enter"

stage "App Store Connect: $LANG_NAME screenshots"
step "Back on the version page ($LANG_NAME), under Previews and Screenshots → iPhone 6.9\" Display,"
step "drag in all six images from the folder that just opened, in order 01 → 06."
open_folder "$SHOTS/iphone-1206x2622"
note "Smaller iPhone sizes scale down from the 6.9\" set, so they're optional."
pause "Uploaded and saved? Press Enter"

stage "Play Console: $LANG_NAME translation"
open_url "https://play.google.com/console"
step "Pinch → Grow users → Store presence → Main store listing."
step "Manage translations → Add your own translations → tick $PLAY_LANG → Apply."
step "Switch the listing to $PLAY_LANG and paste each field."
copy_field "App name" "$(listing "$LANG_CODE" "Google Play" "App name")"
copy_field "Short description" "$(listing "$LANG_CODE" "Google Play" "Short description")"
copy_field "Full description" "$(listing "$LANG_CODE" "Full description")"
pause "Pasted all three? Press Enter"

stage "Play Console: $LANG_NAME screenshots"
step "Same $PLAY_LANG listing → Phone screenshots: remove the inherited English ones,"
step "then upload all six from the folder that just opened, in order 01 → 06."
open_folder "$SHOTS/google-play-1080x1920"
note "Keep the English feature graphic and icon."
step "Click Save, then send the change for review (Publishing overview)."
pause "Saved? Press Enter"

finish
note "App Store: the $LANG_NAME name, subtitle and keywords go live with the next approved version."
note "Next: docs/plan/ISRAEL-SOFT-LAUNCH.md"
}

run_wizard "$@"; exit
